[Form]
public class METDataManagementWorkspaceDataProjectsFormPart extends FormRun
{
    private QueryBuildRange dataProjectFilterRange;
    private DMFOperationType operationType;
    private QueryBuildRange projectCategoryFilterRange;
    private DMFProjectCategory projectCategory;
    private DMFSingleUseDefinitionGroup singleUseDefinitionGroupOnly = NoYes::No;
    private MenuItemName callingMenuItemName;
    private boolean includeSingleUseProjects;

}

public void init()
{
    includeSingleUseProjects = false;

    switch (this.args().parmEnumType())
    {
        case enumNum(NoYes):
            operationType = DMFOperationType::All;
            projectCategory = DMFProjectCategory::Project;
            singleUseDefinitionGroupOnly = NoYes::Yes;
            break;

        case enumNum(DMFOperationType):
            operationType = this.args().parmEnum();
            projectCategory = DMFProjectCategory::Project;
            break;

        case enumNum(DMFProjectCategory):
            operationType = DMFOperationType::All;
            projectCategory = this.args().parmEnum();
            break;

        default:
            operationType = DMFOperationType::All;
            projectCategory = DMFProjectCategory::Project;
            break;
    }

    callingMenuItemName = this.args().menuItemName();

    super();

}

private void setExportAndDownload()
{
    boolean enableButton = true;
    DMFDefinitionGroupEntity definitionGroupEntity;

    // Disable if no entities in the project
    select firstonly definitionGroupEntity
        where definitionGroupEntity.DefinitionGroup == DMFDefinitionGroup.DefinitionGroupName;

    if (!definitionGroupEntity)
    {
        enableButton = false;
    }

    // Disable if source type is EntityDB
    DMFDataSource dataSource;

    select firstonly type from dataSource
        join definitionGroupEntity
        where dataSource.SourceName == definitionGroupEntity.source
            && definitionGroupEntity.DefinitionGroup == DMFDefinitionGroup.DefinitionGroupName;

    enableButton = enableButton && (dataSource.Type != DMFSourceType::EntityDB);

    ExportAndDownload.enabled(enableButton);
}

private void setReExecuteDataProject()
{
    boolean isImportExport = (DMFDefinitionGroup.OperationType == DMFOperationType::Import
        || DMFDefinitionGroup.OperationType == DMFOperationType::Export);

    ReExecuteDataProject.enabled(isImportExport);
}

/// <summary>
/// Exposes form part data source for refresh from other forms.
/// </summary>
private void refreshForm()
{
    DMFDefinitionGroup_ds.research(true);
    DMFDefinitionGroup_ds.refresh();
}

/// <summary>
/// Exposes the name of the calling menu item.
/// </summary>
/// <returns>The menu item which called this form part.</returns>
private MenuItemName getFormPartMenuItemName()
{
    return callingMenuItemName;
}

private DMFFormView getFormView()
{
    DMFFormView formView;

    if (DMFFormViewUserParameters::isGlobalOverrideActive())
    {
        formView = DMFParameters::find().DefaultFormView;
    }
    else
    {
        DMFFormViewUserParameters userFormParameters = DMFFormViewUserParameters::findByUserId(curUserId());

        if (userFormParameters)
        {
            formView = userFormParameters.QuickImportExportViewMode;
        }
    }

    return formView;
}

private void loadDataProjectsforDMFOperationType(Args _args)
{

    DMFFormView formView = element.getFormView();

    // Load data project
    MenuFunction menuFunction;
    switch (DMFDefinitionGroup.OperationType)
    {
        case (DMFOperationType::Export):
            if (formView == DMFFormView::EnhancedView)
            {
                menuFunction = new MenuFunction(MenuItemDisplayStr(DMFQuickExportEnhanced), MenuItemType::Display);
            }
            else
            {
                menuFunction = new MenuFunction(MenuItemDisplayStr(DMFQuickExport), MenuItemType::Display);
            }
            break;

        case (DMFOperationType::Import):
            if (formView == DMFFormView::EnhancedView)
            {
                menuFunction = new MenuFunction(MenuItemDisplayStr(DMFQuickImportEnhanced), MenuItemType::Display);
            }
            else
            {
                menuFunction = new MenuFunction(MenuItemDisplayStr(DMFQuickImport), MenuItemType::Display);
            }
            break;
        case (DMFOperationType::Company):
            menuFunction = new MenuFunction(MenuItemDisplayStr(DMFQuickCopyCompanyEnhanced), MenuItemType::Display);
            break;
    }

    if (menuFunction && MenuFunction.checkAccessRights())
    {
        menuFunction.run(_args);
    }
}

private boolean allProjectsTab()
{
    return operationType == DMFOperationType::All && projectCategory == DMFProjectCategory::Project && singleUseDefinitionGroupOnly == NoYes::No;
}

private boolean singleUserProjectsTab()
{
    return operationType == DMFOperationType::All && projectCategory == DMFProjectCategory::Project && singleUseDefinitionGroupOnly == NoYes::Yes;
}

public void updateSingleUseProjectFilter()
{
    if (includeSingleUseProjects)
    {
        QueryBuildRange qbr = this.queryBuildDataSource().findRange(fieldNum(DMFDefinitionGroup, SingleUse));
        if (qbr)
        {
            this.queryBuildDataSource().clearRange(fieldNum(DMFDefinitionGroup, SingleUse));
        }
    }
    else
    {
        QueryBuildRange singleUseFilterRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(DMFDefinitionGroup, SingleUse));
        singleUseFilterRange.value(queryValue(NoYes::No));
    }

    this.executeQuery();
}

public void init()
{
    super();

    str queryValue = METDMFFormUtil::getQueryValueForOperationType(operationType);
    dataProjectFilterRange = METDMFFormUtil::setDataProjectFilterRange(this.queryBuildDataSource());
    dataProjectFilterRange.value(queryValue);

    queryValue = METDMFFormUtil::getQueryValueForProjectCategory(projectCategory);
    projectCategoryFilterRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(DMFDefinitionGroup, ProjectCategory));
    projectCategoryFilterRange.value(queryValue);


    // UI handling of single-use projects - set range on the DMFDefinitionGroup.SingleUse field
    // for the All projects tab
    //  [1] If the user has chosen to include single use projects, then clear this field range from the query.  This is truly "All projects"
    //  [2] If the user has chosen to exclude single use proejcts, the add a range with value NO
    // for the single use ("Package API") tab
    //  [3] Add a rangewith value YES
    // for all other tab
    //  [4] Add a range with value NO

    if (includeSingleUseProjects && element.allProjectsTab())   // [1]
    {
        QueryBuildRange qbr = this.queryBuildDataSource().findRange(fieldNum(DMFDefinitionGroup, SingleUse));
        if (qbr)
        {
            this.queryBuildDataSource().clearRange(fieldNum(DMFDefinitionGroup, SingleUse));
        }
    }
    else
    {
        QueryBuildRange singleUseFilterRange = SysQuery::findOrCreateRange(this.queryBuildDataSource(), fieldNum(DMFDefinitionGroup, SingleUse));

        if (element.singleUserProjectsTab()) // [3]
        {
            singleUseFilterRange.value(queryValue(NoYes::Yes));
        }
        else // [2], [4]
        {
            singleUseFilterRange.value(queryValue(NoYes::No));
        }
    }



    METDMFFormUtil::setDataSourceFilterByLegalEntity(this.query());

    //If data management form is opened from the entity list page we need to filter data projects to show only related ones
    if (element.args().caller() is FormRun)
    {
        FormRun callerFormRun = element.args().caller();

        if (callerFormRun.args().record().RecId != 0 && callerFormRun.args().record().TableId == tableNum(DMFEntity))
        {
            DMFEntity               dmfEntity = callerFormRun.args().record();
            QueryBuildDataSource    qbds = this.queryBuildDataSource();
            qbds = qbds.addDataSource(tableNum(DMFDefinitionGroupEntity));
            qbds.relations(true);
            qbds.JoinMode(JoinMode::ExistsJoin);

            qbds.addRange(fieldNum(DMFDefinitionGroupEntity, Entity)).value(dmfEntity.EntityName);
        }
    }
}

public void selectionChanged()
{
    super();

    Array array = DMFDefinitionGroup_ds.recordsMarked();
    if (Array.lastIndex() <= 1)
    {
        element.setExportAndDownload();

        element.setReExecuteDataProject();
    }
}

/// <summary>
///  Loads the data project when Load project button is clicked.
/// </summary>
public void clicked()
{
    super();

    Args args = new Args();
    args.caller(this.formRun());
    args.record(DMFDefinitionGroup);
    args.lookupRecord(DMFDefinitionGroup);

    element.loadDataProjectsforDMFOperationType(args);
}

/// <summary>
/// Load data project when name is clicked
/// </summary>
public void jumpRef()
{
    super();

    Args args = new Args();
    args.caller(this.formRun());
    args.record(DMFDefinitionGroup);
    args.lookupRecord(DMFDefinitionGroup);

    element.loadDataProjectsforDMFOperationType(args);

}
